$projects = @(
  'E:\project\temu',
  'E:\project\清泉跨境系统（企业级）',
  'E:\project\海外TK店铺广告投流数据自动化监测'
)
foreach ($p in $projects) {
  Write-Output "===== $p ====="
  if (Test-Path $p) {
    Write-Output "EXISTS"
    # recent files modified today
    $today = (Get-Date).Date
    $recent = Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue |
      Where-Object { $_.LastWriteTime -ge $today -and $_.FullName -notmatch '\\node_modules\\|\\\.git\\|\\__pycache__\\|\\dist\\|\\build\\|\\\.next\\|\\venv\\|\\env\\' } |
      Sort-Object LastWriteTime -Descending |
      Select-Object -First 40 FullName, LastWriteTime, Length
    $recent | ForEach-Object { Write-Output ("{0} | {1}" -f $_.LastWriteTime.ToString('HH:mm:ss'), $_.FullName.Replace($p, '.')) }
    # git status if repo
    if (Test-Path (Join-Path $p '.git')) {
      Write-Output '--- git log today ---'
      Push-Location $p
      git log --since='2026-07-31 00:00:00' --pretty=format:'%h %ad %s' --date=format:'%H:%M' 2>$null
      Write-Output ''
      git log -10 --pretty=format:'%h %ad %s' --date=format:'%Y-%m-%d %H:%M' 2>$null
      Write-Output ''
      Pop-Location
    }
  } else {
    Write-Output 'NOT FOUND'
  }
}

# Temu key file changes - look at diffs via file content summaries
